with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.getenv('AQ_CHROMIUM','/usr/bin/chromium'),headless=True,args=['--no-sandbox','--disable-dev-shm-usage']);p=b.new_page(viewport={'width':1440,'height':900});p.on('pageerror',lambda e:errors.append(str(e)));p.evaluate('''()=>{for(const k of ['localStorage','sessionStorage']){let m=new Map;Object.defineProperty(window,k,{value:{getItem:k=>m.get(k)??null,setItem:(k,v)=>m.set(k,String(v)),removeItem:k=>m.delete(k)}})}}''');p.set_content(H.read_text(),wait_until='load');assert p.evaluate('typeof ALLY_DEBUG==="undefined"');p.locator('#home-map').click();assert p.locator('.map-card').count()==25;assert p.locator('.aq18-map-group').count()==5;assert '0/31' in p.locator('.aq-campaign-count').inner_text();assert '0/31 charms' in p.locator('.aq-scrapbook-link').inner_text();checks.append('25 map cards, five chapter headings, 31-room counters');p.screenshot(path=str(Q/'final-map.png'));p.locator('.aq-scrapbook-link button').click();assert p.locator('.aq-note-card').count()==31;assert '0/31 notes' in p.locator('.aq-scrap-summary').inner_text();assert '0/31 friendship notes' in p.locator('.aq-crew-favors').inner_text();p.locator('[data-scrap-close]').click();checks.append('31 field notes and correct scrapbook counters');p.set_viewport_size({'width':390,'height':844});p.screenshot(path=str(Q/'final-map-portrait.png'));assert p.locator('.map-card').count()==25;assert not errors,errors;checks.append('portrait resize, production hooks absent, no uncaught errors');b.close()
